window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["dell-1996"]={html:"<div class=\"own-dell-1996\">\n  <!-- ── PHONE FRAME (the literal black page border) ─────────────────────── -->\n  <div class=\"dl-frame\">\n    <!-- top banner: BUILD YOUR OWN COMPUTER. ONLINE. + BUY a DELL + phone -->\n    <div class=\"dl-banner\">\n      <div class=\"dl-banner-left\">\n        <p class=\"dl-banner-head\">BUILD YOUR OWN OPERATIONS BOARD. ONLINE.</p>\n        <p class=\"dl-banner-sub\">Northwind Direct &mdash; enterprise analytics, shipped to your floor.</p>\n      </div>\n      <div class=\"dl-banner-right\">\n        <span class=\"dl-buy\" aria-label=\"Buy Northwind\"><span class=\"dl-buy-a\">a</span>BUY <span class=\"dl-buy-brand\">NORTHWIND</span></span>\n        <span class=\"dl-phone\">1-800-213-DELL</span>\n      </div>\n    </div>\n\n    <!-- ── eyebrow: DIMENSION DESKTOPS ─────────────────────────────────────── -->\n    <h1 class=\"dl-eyebrow dl-eyebrow-olive\">NORTHWIND OPERATIONS SUITES</h1>\n\n    <!-- ── two-column outer table: left rail + right product stack ─────────── -->\n    <div class=\"dl-body\">\n      <div class=\"dl-rail\">\n        <!-- red CTA panel (one per page) -->\n        <div class=\"dl-cta\">\n          <p>At Northwind.com, we&rsquo;ll help you find the right board, model it, price it, and put it on the floor &mdash; all before the next shift.</p>\n          <p class=\"dl-cta-link\"><a href=\"#\">Configure &amp; Buy &raquo;</a></p>\n        </div>\n\n        <!-- round award seal -->\n        <div class=\"dl-seal\" aria-label=\"Readers' Choice award\">\n          <span class=\"dl-seal-top\">NORTHWIND</span>\n          <span class=\"dl-seal-mid\">PC&nbsp;MAGAZINE</span>\n          <span class=\"dl-seal-bot\">READERS' CHOICE</span>\n        </div>\n\n        <!-- icon-label nav grid -->\n        <div class=\"dl-iconnav\">\n          <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art dl-icon-find\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"10\" cy=\"10\" r=\"5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"m14 14 5 5\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></span><span class=\"dl-icon-lbl\">FIND</span></a>\n          <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 11 12 4l8 7v9h-5v-6H9v6H4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg></span><span class=\"dl-icon-lbl\">HOME</span></a>\n          <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16l-1.2 13H5.2z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><path d=\"M9 7a3 3 0 0 1 6 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></span><span class=\"dl-icon-lbl\">ONLINE STORE</span></a>\n          <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M14 6a4 4 0 0 0-5 5l-5 5 2 2 5-5a4 4 0 0 0 5-5z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg></span><span class=\"dl-icon-lbl\">SERVICE &amp; SUPPORT</span></a>\n        </div>\n      </div>\n\n      <div class=\"dl-stack\">\n        <!-- ribbon card: sage -->\n        <div class=\"dl-ribbon\">\n          <div class=\"dl-ribbon-title\">NORTHWIND THROUGHPUT BOARD</div>\n          <div class=\"dl-ribbon-body dl-tint-sage\">\n            <div class=\"dl-ribbon-copy\">\n              <p>Units per day across every line, reconciled each shift. Watch the number the whole plant agrees on.</p>\n              <p class=\"dl-ribbon-links\"><a href=\"#\">See it live &raquo;</a> &nbsp;·&nbsp; <a href=\"#\">Configure</a></p>\n            </div>\n            <div class=\"dl-notch\" aria-hidden=\"true\"><span>412k</span></div>\n          </div>\n        </div>\n\n        <!-- ribbon card: salmon + NEW burst -->\n        <div class=\"dl-ribbon\">\n          <div class=\"dl-ribbon-title\">NORTHWIND YIELD ANALYSER</div>\n          <div class=\"dl-ribbon-body dl-tint-salmon\">\n            <span class=\"dl-burst\" aria-hidden=\"true\">NEW!</span>\n            <div class=\"dl-ribbon-copy\">\n              <p>Line yield with drift detection. Flags a slipping line before the shift finds out the hard way. <a href=\"#\">Learn more</a></p>\n              <p class=\"dl-ribbon-links\"><a href=\"#\">Add to board &raquo;</a></p>\n            </div>\n            <div class=\"dl-notch\" aria-hidden=\"true\"><span>94.6%</span></div>\n          </div>\n        </div>\n\n        <!-- ribbon card: periwinkle -->\n        <div class=\"dl-ribbon\">\n          <div class=\"dl-ribbon-title\">NORTHWIND COST LEDGER</div>\n          <div class=\"dl-ribbon-body dl-tint-periwinkle\">\n            <div class=\"dl-ribbon-copy\">\n              <p>Cost per unit, fully landed, with the lineage behind every number. Certified for the audit desk. <a href=\"#\">Learn more</a></p>\n              <p class=\"dl-ribbon-links\"><a href=\"#\">Compare boards &raquo;</a></p>\n            </div>\n            <div class=\"dl-notch\" aria-hidden=\"true\"><span>$2.41</span></div>\n          </div>\n        </div>\n\n        <!-- two-up mini cards: lime + peach -->\n        <div class=\"dl-twoup\">\n          <div class=\"dl-ribbon\">\n            <div class=\"dl-ribbon-title\">REGIONS BOARD</div>\n            <div class=\"dl-ribbon-body dl-tint-lime\">\n              <div class=\"dl-ribbon-copy\"><p>Twelve regions on one governed model. <a href=\"#\">Learn more</a></p></div>\n            </div>\n          </div>\n          <div class=\"dl-ribbon\">\n            <div class=\"dl-ribbon-title\">SHIFT DIGESTS</div>\n            <div class=\"dl-ribbon-body dl-tint-peach\">\n              <div class=\"dl-ribbon-copy\"><p>Every shift, the reconciled board in their inbox. <a href=\"#\">Learn more</a></p></div>\n            </div>\n          </div>\n        </div>\n\n        <!-- search form (HTML 3.2 widget) -->\n        <div class=\"dl-formrow\">\n          <label class=\"dl-form-lbl\" for=\"dlSearch\">Search Northwind:</label>\n          <input class=\"dl-input\" id=\"dlSearch\" type=\"text\" value=\"\">\n          <button class=\"dl-btn dl-btn-primary\" type=\"button\">Go</button>\n          <button class=\"dl-btn\" type=\"button\">Browse</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- ── footer band ─────────────────────────────────────────────────────── -->\n    <div class=\"dl-foot\">\n      <div class=\"dl-foot-iconnav\">\n        <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art dl-icon-find\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"10\" cy=\"10\" r=\"5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"m14 14 5 5\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></span><span class=\"dl-icon-lbl\">FIND</span></a>\n        <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 11 12 4l8 7v9h-5v-6H9v6H4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg></span><span class=\"dl-icon-lbl\">HOME</span></a>\n        <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16l-1.2 13H5.2z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><path d=\"M9 7a3 3 0 0 1 6 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></span><span class=\"dl-icon-lbl\">ONLINE STORE</span></a>\n        <a class=\"dl-icon\" href=\"#\"><span class=\"dl-icon-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M14 6a4 4 0 0 0-5 5l-5 5 2 2 5-5a4 4 0 0 0 5-5z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg></span><span class=\"dl-icon-lbl\">SERVICE &amp; SUPPORT</span></a>\n      </div>\n      <p class=\"dl-foot-small\">\n        <a class=\"dl-copyright\" href=\"#\">Copyright</a> &copy; 1996&ndash;2026 Northwind Direct, Inc. &nbsp;(Terms of Use) &nbsp;·&nbsp; Sample data, showcase only.\n      </p>\n      <p class=\"dl-foot-small\">This site is best viewed with browser versions 3.0 and higher. Prices and specifications valid in the Philippines only.</p>\n    </div>\n  </div>\n</div>\n",css:"/* ══ NORTHWIND — in Dell 1996's design language, for showcase.html ══════════\n   Catalog-era enterprise web: a literal black page frame, flat color-block\n   \"ribbon cards\" tinted in the eight catalog tints, chunky Arial Black display\n   eyebrows, Helvetica Bold row titles, Times Roman body copy, hand-cut GIF\n   sticker overlays (the yellow BUY a DELL tab, the angled NEW! burst, the round\n   red award seal), and a Netscape-blue underlined link. Square corners\n   everywhere except award seals. No gradients, no soft shadows. */\n\n.own-dell-1996 {\n  --primary: #e91d2a;\n  --on-primary: #ffffff;\n  --canvas: #ffffff;\n  --ink: #000000;\n  --frame-ink: #000000;\n  --yellow-sticker: #fcc20f;\n  --purple-stripe: #6a26a4;\n  --link: #0000ee;\n\n  --tint-olive: #8e8a25;\n  --tint-sage: #b3bd95;\n  --tint-salmon: #d77a7a;\n  --tint-peach: #e6915d;\n  --tint-lime: #c0d4a7;\n  --tint-sky: #9ab6c8;\n  --tint-steel: #a5b8c0;\n  --tint-periwinkle: #8c9ae0;\n\n  --font-display: 'Arial Black', 'Helvetica', system-ui, sans-serif;\n  --font-ui: 'Helvetica', 'Arial', system-ui, sans-serif;\n  --font-body: 'Times New Roman', 'Times', serif;\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--frame-ink);\n  padding: 8px;\n  color: var(--ink);\n  font-family: var(--font-body);\n  font-size: 14px;\n  line-height: 1.4;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-dell-1996 *, .own-dell-1996 *::before, .own-dell-1996 *::after { box-sizing: border-box; }\n.own-dell-1996 a { color: var(--link); text-decoration: underline; }\n.own-dell-1996 button { font: inherit; cursor: pointer; }\n.own-dell-1996 :focus-visible { outline: 2px dashed var(--primary); outline-offset: 2px; }\n\n/* ── the white page inside the frame ─────────────────────────────────────── */\n.own-dell-1996 .dl-frame { background: var(--canvas); padding: 0; }\n\n/* ── top banner ────────────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-banner { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 10px 16px; background: var(--frame-ink); color: var(--canvas); }\n.own-dell-1996 .dl-banner-head { font-family: var(--font-ui); font-size: 16px; font-weight: 700; line-height: 1.2; }\n.own-dell-1996 .dl-banner-sub { font-family: var(--font-body); font-size: 12px; color: #d8d8d8; margin-top: 2px; }\n.own-dell-1996 .dl-banner-right { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }\n.own-dell-1996 .dl-buy { display: inline-flex; align-items: center; gap: 4px; padding: 4px 8px; background: var(--yellow-sticker); color: var(--ink); border: 1px solid var(--frame-ink); font-family: var(--font-ui); font-size: 12px; font-weight: 700; }\n.own-dell-1996 .dl-buy-a { display: inline-block; padding: 0 3px; background: var(--purple-stripe); color: var(--canvas); font-style: normal; }\n.own-dell-1996 .dl-buy-brand { color: var(--ink); }\n.own-dell-1996 .dl-phone { font-family: var(--font-ui); font-size: 16px; font-weight: 700; color: var(--primary); white-space: nowrap; }\n\n/* ── section eyebrow block ─────────────────────────────────────────────────── */\n.own-dell-1996 .dl-eyebrow { font-family: var(--font-display); font-weight: 900; font-size: clamp(26px, 3.6cqi, 36px); line-height: 1; padding: 22px 16px; margin: 0; color: var(--ink); }\n.own-dell-1996 .dl-eyebrow-olive { background: var(--tint-olive); }\n\n/* ── two-column body ───────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-body { display: grid; grid-template-columns: 28% 72%; gap: 0; padding: 24px 16px 32px; max-width: 1000px; margin: 0 auto; }\n.own-dell-1996 .dl-rail { display: grid; gap: 20px; align-content: start; padding-right: 20px; }\n.own-dell-1996 .dl-stack { display: grid; gap: 20px; align-content: start; }\n\n/* ── red CTA panel (one per page) ─────────────────────────────────────────── */\n.own-dell-1996 .dl-cta { padding: 16px; background: var(--primary); color: var(--on-primary); border: 1px solid var(--frame-ink); }\n.own-dell-1996 .dl-cta p { color: var(--on-primary); }\n.own-dell-1996 .dl-cta-link a { color: var(--on-primary); }\n\n/* ── award seal ────────────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-seal { justify-self: center; width: 96px; height: 96px; border-radius: 9999px; display: grid; place-content: center; text-align: center; gap: 2px; background: var(--primary); color: var(--canvas); border: 3px solid var(--canvas); outline: 2px solid var(--primary); font-family: var(--font-ui); font-weight: 700; line-height: 1; }\n.own-dell-1996 .dl-seal-top { font-size: 8px; letter-spacing: .5px; }\n.own-dell-1996 .dl-seal-mid { font-size: 11px; }\n.own-dell-1996 .dl-seal-bot { font-size: 7px; letter-spacing: .3px; }\n\n/* ── icon-label nav ────────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-iconnav { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; border-top: 1px solid var(--frame-ink); padding-top: 16px; }\n.own-dell-1996 .dl-icon { display: grid; justify-items: center; gap: 4px; color: var(--ink); text-decoration: none; }\n.own-dell-1996 .dl-icon-art { display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid var(--frame-ink); }\n.own-dell-1996 .dl-icon-art svg { width: 20px; height: 20px; }\n.own-dell-1996 .dl-icon-find { background: var(--canvas); }\n.own-dell-1996 .dl-icon-lbl { font-family: var(--font-ui); font-size: 11px; font-weight: 700; letter-spacing: .3px; }\n.own-dell-1996 .dl-iconnav a:hover .dl-icon-art { background: var(--yellow-sticker); }\n\n/* ── ribbon cards ──────────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-ribbon { border: 1px solid var(--frame-ink); }\n.own-dell-1996 .dl-ribbon-title { padding: 6px 12px; background: var(--canvas); color: var(--ink); border-bottom: 1px solid var(--frame-ink); font-family: var(--font-ui); font-size: 14px; font-weight: 700; letter-spacing: .2px; }\n.own-dell-1996 .dl-ribbon-body { position: relative; display: grid; grid-template-columns: 1fr auto; gap: 12px; padding: 12px 16px; }\n.own-dell-1996 .dl-ribbon-copy p { margin: 0 0 6px; }\n.own-dell-1996 .dl-ribbon-links { font-size: 12px; }\n.own-dell-1996 .dl-tint-sage { background: var(--tint-sage); }\n.own-dell-1996 .dl-tint-salmon { background: var(--tint-salmon); }\n.own-dell-1996 .dl-tint-periwinkle { background: var(--tint-periwinkle); }\n.own-dell-1996 .dl-tint-lime { background: var(--tint-lime); }\n.own-dell-1996 .dl-tint-peach { background: var(--tint-peach); }\n.own-dell-1996 .dl-tint-sky { background: var(--tint-sky); }\n.own-dell-1996 .dl-tint-steel { background: var(--tint-steel); }\n\n/* product photo notch (beveled, hard-edged) */\n.own-dell-1996 .dl-notch { display: grid; place-items: center; width: 116px; height: 92px; background: var(--canvas); border: 1px solid var(--frame-ink); box-shadow: 3px 3px 0 0 var(--frame-ink), inset 2px 2px 0 0 #c9c9c9, inset -2px -2px 0 0 #f4f4f4; }\n.own-dell-1996 .dl-notch span { font-family: var(--font-display); font-size: 24px; line-height: 1; }\n\n/* NEW! burst sticker */\n.own-dell-1996 .dl-burst { position: absolute; top: -12px; right: 14px; padding: 4px 8px; background: var(--yellow-sticker); color: var(--ink); border: 1px solid var(--frame-ink); font-family: var(--font-ui); font-size: 12px; font-weight: 700; transform: rotate(12deg); box-shadow: 2px 2px 0 0 var(--frame-ink); }\n\n/* ── two-up mini ribbons ────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-twoup { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n\n/* ── search form (HTML 3.2 widget) ─────────────────────────────────────────── */\n.own-dell-1996 .dl-formrow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 14px 16px; border: 1px solid var(--frame-ink); background: #f4f0e4; }\n.own-dell-1996 .dl-form-lbl { font-family: var(--font-ui); font-size: 12px; font-weight: 700; }\n.own-dell-1996 .dl-input { flex: 1; min-width: 160px; padding: 4px 6px; border: 1px solid var(--frame-ink); background: var(--canvas); color: var(--ink); font-family: var(--font-body); font-size: 14px; }\n.own-dell-1996 .dl-btn { padding: 6px 16px; border: 1px solid var(--frame-ink); background: var(--canvas); color: var(--ink); font-family: var(--font-ui); font-size: 12px; font-weight: 700; box-shadow: 2px 2px 0 0 var(--frame-ink); }\n.own-dell-1996 .dl-btn:active { box-shadow: none; transform: translate(2px, 2px); }\n.own-dell-1996 .dl-btn-primary { background: var(--frame-ink); color: var(--on-primary); }\n\n/* ── footer band ───────────────────────────────────────────────────────────── */\n.own-dell-1996 .dl-foot { border-top: 1px solid var(--frame-ink); padding: 16px; max-width: 1000px; margin: 0 auto; }\n.own-dell-1996 .dl-foot-iconnav { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; padding-bottom: 14px; border-bottom: 1px solid #4a7a3a; }\n.own-dell-1996 .dl-foot-iconnav .dl-icon-art { width: 28px; height: 28px; }\n.own-dell-1996 .dl-foot-small { margin-top: 10px; font-size: 12px; color: #333; }\n.own-dell-1996 .dl-copyright { color: var(--link); }\n\n/* ── responsive (container queries on the showcase frame) ─────────────────── */\n@container frame (max-width: 1100px) {\n  .own-dell-1996 .dl-body { max-width: none; }\n}\n@container frame (max-width: 760px) {\n  .own-dell-1996 { padding: 4px; }\n  .own-dell-1996 .dl-body { grid-template-columns: 1fr; }\n  .own-dell-1996 .dl-rail { padding-right: 0; padding-bottom: 20px; border-bottom: 1px solid var(--frame-ink); }\n  .own-dell-1996 .dl-iconnav { grid-template-columns: repeat(2, 1fr); }\n  .own-dell-1996 .dl-ribbon-body { grid-template-columns: 1fr; }\n  .own-dell-1996 .dl-notch { width: 100%; height: 72px; }\n  .own-dell-1996 .dl-twoup { grid-template-columns: 1fr; }\n  .own-dell-1996 .dl-foot-iconnav { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-dell-1996 { padding: 2px; }\n  .own-dell-1996 .dl-banner { padding: 8px 10px; }\n  .own-dell-1996 .dl-banner-right { gap: 8px; }\n  .own-dell-1996 .dl-iconnav { grid-template-columns: 1fr; }\n  .own-dell-1996 .dl-formrow { flex-direction: column; align-items: stretch; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-dell-1996 *, .own-dell-1996 *::before, .own-dell-1996 *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in Dell 1996's design language, for showcase.html ══════════
   Registers window.OWN_LAYOUTS['dell-1996'].init(root). A 1996 page carried no
   script; the layout is static, so this only wires the sample search widget and
   returns a cleanup that detaches the one listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['dell-1996'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(s) { return root.querySelector(s); }

      var input = $('#dlSearch');
      var buttons = root.querySelectorAll('.dl-btn');
      on(buttons[1], 'click', function () {
        if (input) { input.value = ''; input.placeholder = 'Sample search — showcase only'; }
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
